#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions (DATA_TYPE, SCALAR_VAL, DEFINE_PROTO_STRUCT, ...)
#include "defines.hpp"

// include benchmark-specific definitions (N, TSTEPS, etc.)
#include "adi.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// Common 2D layout: u[i][j], v[i][j], p[i][j], q[i][j]
struct tuning {
	// j is the inner (fast) dimension, i is the outer (slow) dimension
	DEFINE_PROTO_STRUCT(layout, j_vec ^ i_vec);
} tuning;


// Array initialization: u[i][j] = (i + n - j) / n
void init_array(int n, auto u) {
	using namespace noarr;

	traverser(u).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		u[state] = (num_t)(i + n - j) / n;
	});
}


// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_adi(int tsteps, auto u, auto v, auto p, auto q) {
	using namespace noarr;

	// Problem size (square grid n x n)
	std::size_t n = u | get_length<'i'>();

	// Coefficients (same as in the C version, with _PB_N -> n, _PB_TSTEPS -> tsteps)
	num_t DX = SCALAR_VAL(1.0) / (num_t)n;
	num_t DY = SCALAR_VAL(1.0) / (num_t)n;
	num_t DT = SCALAR_VAL(1.0) / (num_t)tsteps;
	num_t B1 = SCALAR_VAL(2.0);
	num_t B2 = SCALAR_VAL(1.0);
	num_t mul1 = B1 * DT / (DX * DX);
	num_t mul2 = B2 * DT / (DY * DY);

	num_t a = -mul1 / SCALAR_VAL(2.0);
	num_t b = SCALAR_VAL(1.0) + mul1;
	num_t c = a;
	num_t d = -mul2 / SCALAR_VAL(2.0);
	num_t e = SCALAR_VAL(1.0) + mul2;
	num_t f = d;

#pragma scop
	for (int t = 1; t <= tsteps; ++t) {

		// ---------------------------------------------------------------------
		// Column sweep (as in original C code)
		// ---------------------------------------------------------------------
		traverser(u, v, p, q)
			.order(slice<'i'>(1, n - 2)) // i = 1 .. n-2
			.template for_dims<'i'>([&](auto trav_i) {
				auto state_i = trav_i.state();
				auto i_idx = get_index<'i'>(state_i); // corresponds to loop variable i

				// Boundary at j = 0
				auto s_v_0_i = idx<'i', 'j'>(0, i_idx);
				v[s_v_0_i] = SCALAR_VAL(1.0);

				auto s_p_i_0 = idx<'i', 'j'>(i_idx, 0);
				p[s_p_i_0] = SCALAR_VAL(0.0);
				q[s_p_i_0] = v[s_v_0_i];

				// Forward sweep in j: j = 1 .. n-2
				trav_i
					.order(slice<'j'>(1, n - 2))
					.template for_dims<'j'>([&](auto trav_ij) {
						auto state_ij = trav_ij.state();
						auto j_idx = get_index<'j'>(state_ij); // loop variable j

						// p[i][j] = -c / (a*p[i][j-1] + b)
						auto s_p_i_jm1 = idx<'i', 'j'>(i_idx, j_idx - 1);
						num_t denom = a * p[s_p_i_jm1] + b;

						auto s_p_i_j = idx<'i', 'j'>(i_idx, j_idx);
						p[s_p_i_j] = -c / denom;

						// q[i][j] =
						// (-d*u[j][i-1] + (1+2d)*u[j][i] - f*u[j][i+1] - a*q[i][j-1]) /
						// (a*p[i][j-1] + b)
						auto s_q_i_jm1 = s_p_i_jm1;

						auto s_u_j_im1 = idx<'i', 'j'>(j_idx, i_idx - 1);
						auto s_u_j_i   = idx<'i', 'j'>(j_idx, i_idx);
						auto s_u_j_ip1 = idx<'i', 'j'>(j_idx, i_idx + 1);

						num_t numerator =
							-d * u[s_u_j_im1]
							+ (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * d) * u[s_u_j_i]
							- f * u[s_u_j_ip1]
							- a * q[s_q_i_jm1];

						q[s_p_i_j] = numerator / denom;
					});

				// Boundary at j = n-1
				auto s_v_n1_i = idx<'i', 'j'>(n - 1, i_idx);
				v[s_v_n1_i] = SCALAR_VAL(1.0);

				// Backward sweep in j: j = n-2 .. 1
				trav_i
					.order(slice<'j'>(1, n - 2)) // traverse j=1..n-2, map to descending j
					.template for_dims<'j'>([&](auto trav_ij) {
						auto state_ij = trav_ij.state();
						auto j_fwd = get_index<'j'>(state_ij); // 1 .. n-2

						// Map to original descending order: j = n-1 - j_fwd
						std::size_t j = n - 1 - j_fwd; // n-2, n-3, ..., 1

						auto s_v_j_i   = idx<'i', 'j'>(j,     i_idx);
						auto s_v_jp1_i = idx<'i', 'j'>(j + 1, i_idx);
						auto s_p_i_j   = idx<'i', 'j'>(i_idx, j);
						auto s_q_i_j   = s_p_i_j;

						// v[j][i] = p[i][j] * v[j+1][i] + q[i][j]
						v[s_v_j_i] = p[s_p_i_j] * v[s_v_jp1_i] + q[s_q_i_j];
					});
			});

		// ---------------------------------------------------------------------
		// Row sweep (as in original C code)
		// ---------------------------------------------------------------------
		traverser(u, v, p, q)
			.order(slice<'i'>(1, n - 2)) // i = 1 .. n-2
			.template for_dims<'i'>([&](auto trav_i) {
				auto state_i = trav_i.state();
				auto i_idx = get_index<'i'>(state_i); // loop variable i

				// Boundary at j = 0
				auto s_u_i_0 = idx<'i', 'j'>(i_idx, 0);
				u[s_u_i_0] = SCALAR_VAL(1.0);

				auto s_p_i_0 = idx<'i', 'j'>(i_idx, 0);
				p[s_p_i_0] = SCALAR_VAL(0.0);
				q[s_p_i_0] = u[s_u_i_0];

				// Forward sweep in j: j = 1 .. n-2
				trav_i
					.order(slice<'j'>(1, n - 2))
					.template for_dims<'j'>([&](auto trav_ij) {
						auto state_ij = trav_ij.state();
						auto j_idx = get_index<'j'>(state_ij); // loop variable j

						// p[i][j] = -f / (d*p[i][j-1] + e)
						auto s_p_i_jm1 = idx<'i', 'j'>(i_idx, j_idx - 1);
						num_t denom = d * p[s_p_i_jm1] + e;

						auto s_p_i_j = idx<'i', 'j'>(i_idx, j_idx);
						p[s_p_i_j] = -f / denom;

						// q[i][j] =
						// (-a*v[i-1][j] + (1+2a)*v[i][j] - c*v[i+1][j] - d*q[i][j-1]) /
						// (d*p[i][j-1] + e)
						auto s_q_i_jm1 = s_p_i_jm1;

						auto s_v_im1_j = idx<'i', 'j'>(i_idx - 1, j_idx);
						auto s_v_i_j   = idx<'i', 'j'>(i_idx,     j_idx);
						auto s_v_ip1_j = idx<'i', 'j'>(i_idx + 1, j_idx);

						num_t numerator =
							-a * v[s_v_im1_j]
							+ (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * a) * v[s_v_i_j]
							- c * v[s_v_ip1_j]
							- d * q[s_q_i_jm1];

						q[s_p_i_j] = numerator / denom;
					});

				// Boundary at j = n-1
				auto s_u_i_n1 = idx<'i', 'j'>(i_idx, n - 1);
				u[s_u_i_n1] = SCALAR_VAL(1.0);

				// Backward sweep in j: j = n-2 .. 1
				trav_i
					.order(slice<'j'>(1, n - 2))
					.template for_dims<'j'>([&](auto trav_ij) {
						auto state_ij = trav_ij.state();
						auto j_fwd = get_index<'j'>(state_ij); // 1 .. n-2

						// Map to original descending order: j = n-1 - j_fwd
						std::size_t j = n - 1 - j_fwd; // n-2, n-3, ..., 1

						auto s_u_i_j   = idx<'i', 'j'>(i_idx, j);
						auto s_u_i_jp1 = idx<'i', 'j'>(i_idx, j + 1);

						// u[i][j] = p[i][j] * u[i][j+1] + q[i][j]
						u[s_u_i_j] = p[s_u_i_j] * u[s_u_i_jp1] + q[s_u_i_j];
					});
			});
	}
#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// Common lengths for all 2D arrays
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// Allocate bags for u, v, p, q with the same layout
	auto u = noarr::bag(noarr::scalar<num_t>() ^ tuning.layout ^ set_lengths);
	auto v = noarr::bag(noarr::scalar<num_t>() ^ tuning.layout ^ set_lengths);
	auto p = noarr::bag(noarr::scalar<num_t>() ^ tuning.layout ^ set_lengths);
	auto q = noarr::bag(noarr::scalar<num_t>() ^ tuning.layout ^ set_lengths);

	// Initialize u
	init_array(static_cast<int>(n), u.get_ref());

	// Run kernel and measure time
	auto start = std::chrono::high_resolution_clock::now();

	kernel_adi(static_cast<int>(tsteps), u.get_ref(), v.get_ref(), p.get_ref(), q.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Optionally print result (similar role as print_array in the C version)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, u.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
