[[gnu::flatten, gnu::noinline]]
void kernel_adi(int tsteps, auto u, auto v, auto p, auto q) {
	using namespace noarr;

	// All grids are N x N
	std::size_t N = u | get_length<'i'>();

	// Parameter setup (matching original C code)
	num_t DX = SCALAR_VAL(1.0) / (num_t)N;
	num_t DY = SCALAR_VAL(1.0) / (num_t)N;
	num_t DT = SCALAR_VAL(1.0) / (num_t)tsteps;
	num_t B1 = SCALAR_VAL(2.0);
	num_t B2 = SCALAR_VAL(1.0);

	num_t mul1 = B1 * DT / (DX * DX);
	num_t mul2 = B2 * DT / (DY * DY);

	num_t a = -mul1 / SCALAR_VAL(2.0);
	num_t b = SCALAR_VAL(1.0) + mul1;
	num_t c = a;
	num_t d = -mul2 / SCALAR_VAL(2.0);
	num_t e = SCALAR_VAL(1.0) + mul2;
	num_t f = d;

	const num_t one = SCALAR_VAL(1.0);
	const num_t two = SCALAR_VAL(2.0);

#pragma scop
	for (int t = 1; t <= tsteps; t++) {

		// --------------------------------------------------------------------
		// Column sweep (outer loop over i = 1 .. N-2)
		// --------------------------------------------------------------------
		traverser(p, q)
			.order(noarr::slice<'i'>(1, N - 2))
			.template for_dims<'i'>([=](auto trav_i) {
				auto state_i = trav_i.state();
				std::size_t i_idx = get_index<'i'>(state_i);

				// Boundary values for this "column" i
				// v[0][i] = 1.0;
				v[noarr::idx<'i', 'j'>(0, i_idx)] = one;

				// p[i][0] = 0.0; q[i][0] = v[0][i];
				auto pi0 = noarr::idx<'i', 'j'>(i_idx, 0);
				p[pi0] = SCALAR_VAL(0.0);
				q[pi0] = v[noarr::idx<'i', 'j'>(0, i_idx)];

				// Forward sweep over j = 1 .. N-2
				auto trav_forward = trav_i.order(noarr::slice<'j'>(1, N - 2));
				trav_forward.for_each([=](auto state) {
					auto [i, j] = get_indices<'i', 'j'>(state);

					// p[i][j] = -c / (a * p[i][j-1] + b);
					auto state_prev = state - noarr::idx<'j'>(1);
					num_t denom = a * p[state_prev] + b;
					p[state] = -c / denom;

					// q[i][j] =
					//   (-d * u[j][i-1]
					//    + (1 + 2*d) * u[j][i]
					//    - f * u[j][i+1]
					//    - a * q[i][j-1])
					//   / (a * p[i][j-1] + b);
					auto u_j_im1 = noarr::idx<'i', 'j'>(j, i - 1);
					auto u_j_i   = noarr::idx<'i', 'j'>(j, i);
					auto u_j_ip1 = noarr::idx<'i', 'j'>(j, i + 1);

					num_t u_im1 = u[u_j_im1];
					num_t u_i   = u[u_j_i];
					num_t u_ip1 = u[u_j_ip1];

					q[state] = (-d * u_im1
					            + (one + two * d) * u_i
					            - f * u_ip1
					            - a * q[state_prev]) / denom;
				});

				// v[N-1][i] = 1.0;
				v[noarr::idx<'i', 'j'>(N - 1, i_idx)] = one;

				// Backward sweep over j = N-2 .. 1
				auto trav_backward = trav_i.order(noarr::slice<'j'>(1, N - 2));
				trav_backward.for_each([=](auto state) {
					std::size_t i = get_index<'i'>(state);
					std::size_t j_asc = get_index<'j'>(state);     // 1 .. N-2
					std::size_t j_desc = (N - 1) - j_asc;          // N-2 .. 1

					// v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
					auto state_pq     = noarr::idx<'i', 'j'>(i, j_desc);
					auto state_v_curr = noarr::idx<'i', 'j'>(j_desc,     i);
					auto state_v_next = noarr::idx<'i', 'j'>(j_desc + 1, i);

					v[state_v_curr] = p[state_pq] * v[state_v_next] + q[state_pq];
				});
			});

		// --------------------------------------------------------------------
		// Row sweep (outer loop over i = 1 .. N-2)
		// --------------------------------------------------------------------
		traverser(p, q, u, v)
			.order(noarr::slice<'i'>(1, N - 2))
			.template for_dims<'i'>([=](auto trav_i) {
				auto state_i = trav_i.state();
				std::size_t i_idx = get_index<'i'>(state_i);

				// u[i][0] = 1.0;
				// p[i][0] = 0.0;
				// q[i][0] = u[i][0];
				auto ui0 = noarr::idx<'i', 'j'>(i_idx, 0);
				u[ui0] = one;
				p[ui0] = SCALAR_VAL(0.0);
				q[ui0] = u[ui0];

				// Forward sweep over j = 1 .. N-2
				auto trav_forward = trav_i.order(noarr::slice<'j'>(1, N - 2));
				trav_forward.for_each([=](auto state) {
					auto [i, j] = get_indices<'i', 'j'>(state);

					// p[i][j] = -f / (d * p[i][j-1] + e);
					auto state_prev = state - noarr::idx<'j'>(1);
					num_t denom = d * p[state_prev] + e;
					p[state] = -f / denom;

					// q[i][j] =
					//   (-a * v[i-1][j]
					//    + (1 + 2*a) * v[i][j]
					//    - c * v[i+1][j]
					//    - d * q[i][j-1])
					//   / (d * p[i][j-1] + e);
					auto v_im1 = noarr::idx<'i', 'j'>(i - 1, j);
					auto v_i   = noarr::idx<'i', 'j'>(i,     j);
					auto v_ip1 = noarr::idx<'i', 'j'>(i + 1, j);

					num_t vv_im1 = v[v_im1];
					num_t vv_i   = v[v_i];
					num_t vv_ip1 = v[v_ip1];

					q[state] = (-a * vv_im1
					            + (one + two * a) * vv_i
					            - c * vv_ip1
					            - d * q[state_prev]) / denom;
				});

				// u[i][N-1] = 1.0;
				auto uiN1 = noarr::idx<'i', 'j'>(i_idx, N - 1);
				u[uiN1] = one;

				// Backward sweep over j = N-2 .. 1
				auto trav_backward = trav_i.order(noarr::slice<'j'>(1, N - 2));
				trav_backward.for_each([=](auto state) {
					std::size_t i = get_index<'i'>(state);
					std::size_t j_asc = get_index<'j'>(state);     // 1 .. N-2
					std::size_t j_desc = (N - 1) - j_asc;          // N-2 .. 1

					// u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
					auto state_pq      = noarr::idx<'i', 'j'>(i, j_desc);
					auto state_u_curr  = noarr::idx<'i', 'j'>(i, j_desc);
					auto state_u_next  = noarr::idx<'i', 'j'>(i, j_desc + 1);

					u[state_u_curr] = p[state_pq] * u[state_u_next] + q[state_pq];
				});
			});
	}
#pragma endscop
}

