	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// Common lengths for all 2D grids
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// Allocate bags for u, v, p, q
	auto u = noarr::bag(noarr::scalar<num_t>() ^ tuning.grid_layout ^ set_lengths);
	auto v = noarr::bag(noarr::scalar<num_t>() ^ tuning.grid_layout ^ set_lengths);
	auto p = noarr::bag(noarr::scalar<num_t>() ^ tuning.grid_layout ^ set_lengths);
	auto q = noarr::bag(noarr::scalar<num_t>() ^ tuning.grid_layout ^ set_lengths);

	// Initialize u
	init_array(u.get_ref());

	// Start timer
	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_adi((int)tsteps, u.get_ref(), v.get_ref(), p.get_ref(), q.get_ref());

	// Stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print results (prevents dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, u.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print timing
