// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "adi.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// 2D N x N layout: first index 'i' (row), second index 'j' (column)
	DEFINE_PROTO_STRUCT(u_layout, j_vec ^ i_vec);
} tuning;

// Array initialization: u[i][j] = (i + n - j) / n
void init_array(auto u) {
	using namespace noarr;

	auto n = u | get_length<'i'>(); // == get_length<'j'>()

	traverser(u).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		u[state] = static_cast<num_t>(i + n - j) / static_cast<num_t>(n);
	});
}

// Main computational kernel: ADI
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto u, auto v, auto p, auto q) {
	using namespace noarr;

	const auto n = u | get_length<'i'>(); // grid size N

	// Parameter initialization (matches original kernel)
	num_t DX = num_t(1.0) / num_t(n);
	num_t DY = num_t(1.0) / num_t(n);
	num_t DT = num_t(1.0) / num_t(tsteps);
	num_t B1 = num_t(2.0);
	num_t B2 = num_t(1.0);
	num_t mul1 = B1 * DT / (DX * DX);
	num_t mul2 = B2 * DT / (DY * DY);

	num_t a = -mul1 / num_t(2.0);
	num_t b = num_t(1.0) + mul1;
	num_t c = a;
	num_t d = -mul2 / num_t(2.0);
	num_t e = num_t(1.0) + mul2;
	num_t f = d;

#pragma scop
	for (std::size_t t = 0; t < tsteps; t++) {
		// ---------------------------------------------------------------------
		// Column sweep
		// ---------------------------------------------------------------------
		traverser(u, v, p, q).template for_dims<'i'>([&](auto trav_i) {
			auto state_i = trav_i.state();
			auto i = get_index<'i'>(state_i);

			// skip boundary rows (i == 0 or i == n-1)
			if (i == 0 || i == n - 1)
				return;

			// v[0][i] = 1.0;
			v[noarr::idx<'i', 'j'>(0, i)] = num_t(1.0);
			// p[i][0] = 0.0;
			p[noarr::idx<'i', 'j'>(i, 0)] = num_t(0.0);
			// q[i][0] = v[0][i];
			q[noarr::idx<'i', 'j'>(i, 0)] = v[noarr::idx<'i', 'j'>(0, i)];

			// Forward sweep in j: j = 1 .. n-2
			trav_i.template for_each<'j'>([&](auto state) {
				auto [ii, j] = get_indices<'i', 'j'>(state);

				if (j == 0 || j == n - 1)
					return; // use only interior j

				// p[i][j] = -c / (a*p[i][j-1] + b);
				num_t denom_p = a * p[noarr::idx<'i', 'j'>(ii, j - 1)] + b;
				p[state] = -c / denom_p;

				// q[i][j] =
				//   (-d*u[j][i-1] + (1+2*d)*u[j][i] - f*u[j][i+1] - a*q[i][j-1]) /
				//   (a*p[i][j-1] + b);
				num_t q_num =
					(-d * u[noarr::idx<'i', 'j'>(j, ii - 1)] +
					 (num_t(1.0) + num_t(2.0) * d) * u[noarr::idx<'i', 'j'>(j, ii)] -
					 f * u[noarr::idx<'i', 'j'>(j, ii + 1)] -
					 a * q[noarr::idx<'i', 'j'>(ii, j - 1)]);
				num_t q_val = q_num / denom_p;

				q[state] = q_val;
			});

			// v[n-1][i] = 1.0;
			v[noarr::idx<'i', 'j'>(n - 1, i)] = num_t(1.0);

			// Backward substitution in j: j = n-2 .. 1
			//
			// We iterate j_as_k = 0 .. n-1 in increasing order and map
			//   j = n-1 - j_as_k
			// so that j takes values n-2, n-3, ..., 1 in this loop.
			trav_i.template for_each<'j'>([&](auto state) {
				auto [ii, j_as_k] = get_indices<'i', 'j'>(state);

				if (j_as_k == 0 || j_as_k == n - 1)
					return; // only interior j

				std::size_t j = n - 1 - j_as_k; // descending j

				// v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
				v[noarr::idx<'i', 'j'>(j, ii)] =
					p[noarr::idx<'i', 'j'>(ii, j)] *
						v[noarr::idx<'i', 'j'>(j + 1, ii)] +
					q[noarr::idx<'i', 'j'>(ii, j)];
			});
		});

		// ---------------------------------------------------------------------
		// Row sweep
		// ---------------------------------------------------------------------
		traverser(u, v, p, q).template for_dims<'i'>([&](auto trav_i) {
			auto state_i = trav_i.state();
			auto i = get_index<'i'>(state_i);

			// skip boundary rows (i == 0 or i == n-1)
			if (i == 0 || i == n - 1)
				return;

			// u[i][0] = 1.0;
			u[noarr::idx<'i', 'j'>(i, 0)] = num_t(1.0);
			// p[i][0] = 0.0;
			p[noarr::idx<'i', 'j'>(i, 0)] = num_t(0.0);
			// q[i][0] = u[i][0];
			q[noarr::idx<'i', 'j'>(i, 0)] = u[noarr::idx<'i', 'j'>(i, 0)];

			// Forward sweep in j: j = 1 .. n-2
			trav_i.template for_each<'j'>([&](auto state) {
				auto [ii, j] = get_indices<'i', 'j'>(state);

				if (j == 0 || j == n - 1)
					return; // only interior j

				// p[i][j] = -f / (d*p[i][j-1] + e);
				num_t denom_p = d * p[noarr::idx<'i', 'j'>(ii, j - 1)] + e;
				p[state] = -f / denom_p;

				// q[i][j] =
				//   (-a*v[i-1][j] + (1+2*a)*v[i][j] - c*v[i+1][j] - d*q[i][j-1]) /
				//   (d*p[i][j-1] + e);
				num_t q_num =
					(-a * v[noarr::idx<'i', 'j'>(ii - 1, j)] +
					 (num_t(1.0) + num_t(2.0) * a) * v[state] -
					 c * v[noarr::idx<'i', 'j'>(ii + 1, j)] -
					 d * q[noarr::idx<'i', 'j'>(ii, j - 1)]);
				num_t q_val = q_num / denom_p;

				q[state] = q_val;
			});

			// u[i][n-1] = 1.0;
			u[noarr::idx<'i', 'j'>(i, n - 1)] = num_t(1.0);

			// Backward substitution in j: j = n-2 .. 1
			trav_i.template for_each<'j'>([&](auto state) {
				auto [ii, j_as_k] = get_indices<'i', 'j'>(state);

				if (j_as_k == 0 || j_as_k == n - 1)
					return; // only interior j

				std::size_t j = n - 1 - j_as_k; // descending j

				// u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
				u[noarr::idx<'i', 'j'>(ii, j)] =
					p[noarr::idx<'i', 'j'>(ii, j)] *
						u[noarr::idx<'i', 'j'>(ii, j + 1)] +
					q[noarr::idx<'i', 'j'>(ii, j)];
			});
		});
	}
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// 2D grid lengths
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate bags for u, v, p, q
	auto u = noarr::bag(noarr::scalar<num_t>() ^ tuning.u_layout ^ set_lengths);
	auto v = noarr::bag(noarr::scalar<num_t>() ^ tuning.u_layout ^ set_lengths);
	auto p = noarr::bag(noarr::scalar<num_t>() ^ tuning.u_layout ^ set_lengths);
	auto q = noarr::bag(noarr::scalar<num_t>() ^ tuning.u_layout ^ set_lengths);

	// initialize u
	init_array(u.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_adi(tsteps, u.get_ref(), v.get_ref(), p.get_ref(), q.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (similar role as print_array)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' so we print row-major
		noarr::serialize_data(std::cerr, u.get_ref() ^ noarr::hoist<'i'>());
	}

	// print elapsed time
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
