#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions (DATA_TYPE, SCALAR_VAL, N, TSTEPS, DEFINE_PROTO_STRUCT, ...)
#include "defines.hpp"

// include benchmark-specific definitions
#include "adi.hpp"

using num_t = DATA_TYPE;

namespace {

// grid indices: 'x' = first index in C (row), 'y' = second index in C (column)
constexpr auto x_vec = noarr::vector<'x'>();
constexpr auto y_vec = noarr::vector<'y'>();

struct tuning {
	// C arrays are declared as DATA_TYPE u[N][N];
	// second index is contiguous in memory -> layout: y (inner) then x (outer)
	DEFINE_PROTO_STRUCT(grid_layout, y_vec ^ x_vec);
} tuning;

// initialization function
void init_array(std::size_t n, auto u) {
	// u: x × y
	using namespace noarr;

	traverser(u).for_each([=](auto state) {
		auto [x, y] = get_indices<'x', 'y'>(state);
		u[state] = (num_t)(x + n - y) / (num_t)n;
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto u, auto v, auto p, auto q) {
	// all: x × y
	using namespace noarr;

	const std::size_t n = u | get_length<'x'>(); // grid is n × n

	// scalar parameters
	num_t DX = SCALAR_VAL(1.0) / (num_t)n;
	num_t DY = SCALAR_VAL(1.0) / (num_t)n;
	num_t DT = SCALAR_VAL(1.0) / (num_t)tsteps;
	num_t B1 = SCALAR_VAL(2.0);
	num_t B2 = SCALAR_VAL(1.0);
	num_t mul1 = B1 * DT / (DX * DX);
	num_t mul2 = B2 * DT / (DY * DY);

	num_t a = -mul1 / SCALAR_VAL(2.0);
	num_t b = SCALAR_VAL(1.0) + mul1;
	num_t c = a;
	num_t d = -mul2 / SCALAR_VAL(2.0);
	num_t e = SCALAR_VAL(1.0) + mul2;
	num_t f = d;

#pragma scop
	for (std::size_t t = 0; t < tsteps; t++) {
		// ------------------------------------------------------------------
		// Column sweep (sweep along x, one column y at a time)
		// ------------------------------------------------------------------
		traverser(u, v, p, q)
			// i in C runs from 1 to n-2 and is used as the second index -> y ∈ {1, ..., n-2}
			.order(noarr::slice<'y'>(1, n - 2))
			.template for_dims<'y'>([=](auto trav_col) {
				auto col_state = trav_col.state();
				std::size_t i = get_index<'y'>(col_state); // column index (C's i in column sweep)

				// boundary conditions at x = 0
				v[noarr::idx<'x', 'y'>(0, i)] = SCALAR_VAL(1.0);
				p[noarr::idx<'x', 'y'>(i, 0)] = SCALAR_VAL(0.0);
				q[noarr::idx<'x', 'y'>(i, 0)] = v[noarr::idx<'x', 'y'>(0, i)];

				// forward sweep in x-direction: j = 1 .. n-2
				for (std::size_t j = 1; j < n - 1; j++) {
					num_t denom = a * p[noarr::idx<'x', 'y'>(i, j - 1)] + b;

					p[noarr::idx<'x', 'y'>(i, j)] = -c / denom;

					num_t u_j_im1 = u[noarr::idx<'x', 'y'>(j,     i - 1)];
					num_t u_j_i   = u[noarr::idx<'x', 'y'>(j,     i    )];
					num_t u_j_ip1 = u[noarr::idx<'x', 'y'>(j,     i + 1)];
					num_t q_prev  = q[noarr::idx<'x', 'y'>(i,     j - 1)];

					q[noarr::idx<'x', 'y'>(i, j)] =
						(-d * u_j_im1 +
						 (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * d) * u_j_i -
						 f * u_j_ip1 -
						 a * q_prev) / denom;
				}

				// boundary condition at x = n-1
				v[noarr::idx<'x', 'y'>(n - 1, i)] = SCALAR_VAL(1.0);

				// backward substitution in x-direction: j = n-2 .. 1
				for (std::size_t j = n - 2; j > 0; --j) {
					v[noarr::idx<'x', 'y'>(j, i)] =
						p[noarr::idx<'x', 'y'>(i, j)] *
						v[noarr::idx<'x', 'y'>(j + 1, i)] +
						q[noarr::idx<'x', 'y'>(i, j)];
				}
			});

		// ------------------------------------------------------------------
		// Row sweep (sweep along y, one row x at a time)
		// ------------------------------------------------------------------
		traverser(u, v, p, q)
			// i in C runs from 1 to n-2 and is used as the first index here -> x ∈ {1, ..., n-2}
			.order(noarr::slice<'x'>(1, n - 2))
			.template for_dims<'x'>([=](auto trav_row) {
				auto row_state = trav_row.state();
				std::size_t i = get_index<'x'>(row_state); // row index (C's i in row sweep)

				// boundary conditions at y = 0
				u[noarr::idx<'x', 'y'>(i, 0)] = SCALAR_VAL(1.0);
				p[noarr::idx<'x', 'y'>(i, 0)] = SCALAR_VAL(0.0);
				q[noarr::idx<'x', 'y'>(i, 0)] = u[noarr::idx<'x', 'y'>(i, 0)];

				// forward sweep in y-direction: j = 1 .. n-2
				for (std::size_t j = 1; j < n - 1; j++) {
					num_t denom = d * p[noarr::idx<'x', 'y'>(i, j - 1)] + e;

					p[noarr::idx<'x', 'y'>(i, j)] = -f / denom;

					num_t v_im1_j = v[noarr::idx<'x', 'y'>(i - 1, j)];
					num_t v_i_j   = v[noarr::idx<'x', 'y'>(i,     j)];
					num_t v_ip1_j = v[noarr::idx<'x', 'y'>(i + 1, j)];
					num_t q_prev  = q[noarr::idx<'x', 'y'>(i,     j - 1)];

					q[noarr::idx<'x', 'y'>(i, j)] =
						(-a * v_im1_j +
						 (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * a) * v_i_j -
						 c * v_ip1_j -
						 d * q_prev) / denom;
				}

				// boundary condition at y = n-1
				u[noarr::idx<'x', 'y'>(i, n - 1)] = SCALAR_VAL(1.0);

				// backward substitution in y-direction: j = n-2 .. 1
				for (std::size_t j = n - 2; j > 0; --j) {
					u[noarr::idx<'x', 'y'>(i, j)] =
						p[noarr::idx<'x', 'y'>(i, j)] *
						u[noarr::idx<'x', 'y'>(i, j + 1)] +
						q[noarr::idx<'x', 'y'>(i, j)];
				}
			});
	}
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// allocate data (bags own their storage)
	auto set_lengths = noarr::set_length<'x'>(n) ^ noarr::set_length<'y'>(n);

	auto u = noarr::bag(noarr::scalar<num_t>() ^ tuning.grid_layout ^ set_lengths);
	auto v = noarr::bag(noarr::scalar<num_t>() ^ tuning.grid_layout ^ set_lengths);
	auto p = noarr::bag(noarr::scalar<num_t>() ^ tuning.grid_layout ^ set_lengths);
	auto q = noarr::bag(noarr::scalar<num_t>() ^ tuning.grid_layout ^ set_lengths);

	// initialize data
	init_array(n, u.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_adi(tsteps, u.get_ref(), v.get_ref(), p.get_ref(), q.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (if some non-empty program name is provided)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'x' to the top for more natural row-major printing
		noarr::serialize_data(std::cerr, u.get_ref() ^ noarr::hoist<'x'>());
	}

	// print elapsed time in seconds
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
